```javascript
import { mix, uv, color } from 'three/tsl';
import { MeshStandardNodeMaterial } from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const { THREE, fontAtlas, emit } = ctx;
  const { Group, Mesh, PlaneGeometry, Color } = THREE;

  const root = new Group();

  // Color palette from spec
  const colors = {
    paper: '#e8ecf2',
    accent: '#ff2a38',
    hairline: '#23232b',
    gradTop: '#121218',
    gradBottom: '#0b0b10',
  };

  const paperColor = new Color(colors.paper);
  const accentColor = new Color(colors.accent);

  // ─────────────────────────────────────
  // BACKDROP with vertical gradient
  // ─────────────────────────────────────
  const backdropGeom = new PlaneGeometry(6.8, 2.0);
  const backdropMat = new MeshStandardNodeMaterial();
  backdropMat.colorNode = mix(
    color(new Color(colors.gradBottom)),
    color(new Color(colors.gradTop)),
    uv().y
  );
  backdropMat.roughness = 0.6;
  backdropMat.metalness = 0.2;
  backdropMat.transparent = true;

  const backdrop = new Mesh(backdropGeom, backdropMat);
  root.add(backdrop);

  // ─────────────────────────────────────
  // HAIRLINE RULES
  // ─────────────────────────────────────
  const hairlineGeom = new PlaneGeometry(6.8, 0.006);

  // Top hairline
  const hairlineMat1 = new MeshStandardNodeMaterial();
  hairlineMat1.color = new Color(colors.hairline);
  hairlineMat1.roughness = 0.3;
  hairlineMat1.metalness = 0.5;
  hairlineMat1.transparent = true;

  const topHairline = new Mesh(hairlineGeom, hairlineMat1);
  topHairline.position.z = 0.002;
  topHairline.position.y = 0.994;
  root.add(topHairline);

  // Bottom hairline (separating content from legal)
  const hairlineMat2 = new MeshStandardNodeMaterial();
  hairlineMat2.color = new Color(colors.hairline);
  hairlineMat2.roughness = 0.3;
  hairlineMat2.metalness = 0.5;
  hairlineMat2.transparent = true;

  const bottomHairline = new Mesh(hairlineGeom, hairlineMat2);
  bottomHairline.position.z = 0.002;
  bottomHairline.position.y = -0.625;
  root.add(bottomHairline);

  // ─────────────────────────────────────
  // ACCENT BAR (below wordmark)
  // ─────────────────────────────────────
  const accentGeom = new PlaneGeometry(0.3, 0.02);
  const accentMat = new MeshStandardNodeMaterial();
  accentMat.color = accentColor;
  accentMat.emissive = accentColor;
  accentMat.emissiveIntensity = 1.4;
  accentMat.roughness = 0.3;
  accentMat.metalness = 0.1;
  accentMat.transparent = true;

  const accentBar = new Mesh(accentGeom, accentMat);
  accentBar.position.set(-2.9, -0.45, 0.003);
  root.add(accentBar);

  // ─────────────────────────────────────
  // TEXT ELEMENTS
  // ─────────────────────────────────────
  const allText = [];

  // Wordmark
  const wordmark = fontAtlas.createText('NOVA ATELIER', {
    fontSize: 34,
    color: colors.paper,
    align: 'left',
  });
  wordmark.position.set(-2.9, 0.35, 0.01);
  root.add(wordmark);
  allText.push(wordmark);

  // Helper: create a column with header + links
  const createColumn = (headerText, links, xPos, headerY) => {
    const header = fontAtlas.createText(headerText, {
      fontSize: 9,
      color: colors.paper,
      align: 'left',
      letterSpacingPx: 0.12 * 9 / 100,
    });
    header.position.set(xPos, headerY, 0.01);
    root.add(header);
    allText.push(header);

    let yPos = headerY - 0.23;
    for (const linkLabel of links) {
      const linkEl = fontAtlas.createText(linkLabel, {
        fontSize: 13,
        color: colors.paper,
        align: 'left',
      });
      linkEl.position.set(xPos, yPos, 0.01);
      linkEl.userData.isLink = true;
      linkEl.userData.label = linkLabel;
      root.add(linkEl);
      allText.push(linkEl);
      yPos -= 0.235;
    }
  };

  // Three link columns
  createColumn('ATELIER', ['Features', 'Collection', 'Pricing'], -1.0, 0.65);
  createColumn('COMPANY', ['Journal', 'Visit the Atelier', 'Contact'], 0.575, 0.65);
  createColumn('LEGAL', ['Privacy', 'Terms', 'Warranty'], 2.15, 0.65);

  // Legal line (full width)
  const legalLine = fontAtlas.createText(
    '(c) 2026 Nova Atelier. All rights reserved. Machined in Geneva.',
    {
      fontSize: 9,
      color: colors.paper,
      align: 'center',
      maxWidthPx: 680,
      letterSpacingPx: 0.04 * 9 / 100,
    }
  );
  legalLine.position.set(0, -0.85, 0.01);
  root.add(legalLine);
  allText.push(legalLine);

  // ─────────────────────────────────────
  // EVENT HANDLERS & ANIMATIONS
  // ─────────────────────────────────────
  root.userData.opacity = 0;
  const linkTimelines = new Map();

  root.userData.handlers = {
    mouseEnter: (evt) => {
      if (!evt.object?.userData?.isLink) return;
      const obj = evt.object;

      if (linkTimelines.has(obj)) {
        linkTimelines.get(obj).kill();
      }

      const tl = gsap.timeline();
      tl.to(obj.material.color, {
        r: accentColor.r,
        g: accentColor.g,
        b: accentColor.b,
        duration: 0.14,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
      }, 0);
      tl.to(obj.position, {
        z: 0.02,
        duration: 0.14,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
      }, 0);
      linkTimelines.set(obj, tl);
    },

    mouseLeave: (evt) => {
      if (!evt.object?.userData?.isLink) return;
      const obj = evt.object;

      if (linkTimelines.has(obj)) {
        linkTimelines.get(obj).kill();
      }

      const tl = gsap.timeline();
      tl.to(obj.material.color, {
        r: paperColor.r,
        g: paperColor.g,
        b: paperColor.b,
        duration: 0.14,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
      }, 0);
      tl.to(obj.position, {
        z: 0.01,
        duration: 0.14,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
      }, 0);
      linkTimelines.set(obj, tl);
    },

    click: (evt) => {
      if (!evt.object?.userData?.isLink) return;
      const label = evt.object.userData.label;

      const navMap = {
        'Features': 'hub-features',
        'Collection': 'hub-collection',
        'Pricing': 'hub-pricing',
        'Journal': 'hub-journal',
        'Visit the Atelier': 'book-visit',
        'Contact': 'contact',
        'Privacy': 'privacy',
        'Terms': 'terms',
        'Warranty': 'warranty',
      };

      const target = navMap[label];
      if (target) {
        emit('navigate', { to: target });
      }
    },
  };

  // ─────────────────────────────────────
  // ENTRANCE ANIMATION (fade-up)
  // ─────────────────────────────────────
  root.position.y = 0.2;

  const entranceTL = gsap.timeline();

  // Opacity fade
  entranceTL.to(root.userData, {
    opacity: 1,
    duration: 0.5,
    ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
    onUpdate: () => {
      const op = root.userData.opacity;
      backdrop.material.opacity = op;
      topHairline.material.opacity = op;
      bottomHairline.material.opacity = op;
      accentBar.material.opacity = op;
      allText.forEach((t) => {
        if (t.material) t.material.opacity = op;
      });
    },
  }, 0);

  // Translate up (y +0.2 → 0)
  entranceTL.to(root.position, {
    y: 0,
    duration: 0.5,
    ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
  }, 0);

  // ─────────────────────────────────────
  // CLEANUP
  // ─────────────────────────────────────
  root.userData.cleanup = () => {
    entranceTL.kill();
    linkTimelines.forEach((tl) => tl.kill());
    linkTimelines.clear();

    backdropGeom.dispose();
    backdropMat.dispose();
    hairlineGeom.dispose();
    hairlineMat1.dispose();
    hairlineMat2.dispose();
    accentGeom.dispose();
    accentMat.dispose();

    allText.forEach((t) => {
      if (t.geometry) t.geometry.dispose();
      if (t.material) t.material.dispose();
    });
  };

  return root;
}
